import { normalizeText } from "../utils/peaks";

// The catalog is a set of static files generated by scripts/add_peak.py:
// a small manifest plus one file per region (see scripts/README.md).
// "/data/peaks" is served from the "public" folder by Vite.
const CATALOG_URL = "/data/peaks";

// Downloads a JSON file and gives a clear error if something is wrong
async function fetchJson(url, options) {
  const response = await fetch(url, options);

  // fetch does not throw on HTTP errors, so we check manually
  if (!response.ok) {
    throw new Error(`Cannot load ${url} (HTTP ${response.status})`);
  }

  // A missing file can be answered with the home page (HTTP 200): that is not JSON
  try {
    return await response.json();
  } catch {
    throw new Error(`${url} is not valid JSON`);
  }
}

// Loads the whole catalog and returns one list of peaks
export async function fetchPeaks() {
  // "no-cache" makes the browser ask the server whether the manifest changed,
  // so a new import is seen at once. It costs almost nothing: the manifest is small.
  const manifest = await fetchJson(`${CATALOG_URL}/manifest.json`, {
    cache: "no-cache",
  });

  // All region files are downloaded in parallel.
  // The "v" parameter changes when a file changes, so the browser can keep the
  // other files in its cache for a long time.
  const regions = await Promise.all(
    manifest.regions.map(async (region) => ({
      region,
      peaks: await fetchJson(`${CATALOG_URL}/${region.file}?v=${region.version}`),
    }))
  );

  const peaksById = new Map();

  for (const { region, peaks } of regions) {
    for (const peak of peaks) {
      // A peak on a border can be in two regions: the first one wins
      if (peaksById.has(peak.id)) continue;

      peaksById.set(peak.id, {
        ...peak,
        // The files do not contain these fields: they come from the manifest
        country: region.country,
        region: region.region,
        regionCode: region.code,
        // The normalized name is calculated once here, not for every peak
        // at every key press in searchPeaks
        search: normalizeText(peak.name),
      });
    }
  }

  // Highest peaks first: searchPeaks relies on this order,
  // and the files of the regions are not sorted between each other
  return [...peaksById.values()].sort((a, b) => b.elevation - a.elevation);
}